      perf_ctrl_en_q <= (perf_ctrl_en_q & ~wmask[0]) | (req_i.wdata[0] & wmask[0]);
    end
  end
  assign reg2hw_o.perf_ctrl.en.q = perf_ctrl_en_q;

  // PERF_CTRL.CLEAR (wo: registered data plus one-cycle strobe)
  logic perf_ctrl_clear_q;
  logic perf_ctrl_clear_qe;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      perf_ctrl_clear_q  <= '0;
      perf_ctrl_clear_qe <= 1'b0;
    end else begin
      perf_ctrl_clear_qe <= we_perf_ctrl & (|wmask[1]);
      if (we_perf_ctrl) begin
        perf_ctrl_clear_q <= req_i.wdata[1] & wmask[1];
      end
    end
  end
  assign reg2hw_o.perf_ctrl.clear.q  = perf_ctrl_clear_q;
  assign reg2hw_o.perf_ctrl.clear.qe = perf_ctrl_clear_qe;

  // PERF_CTRL.SNAPSHOT (wo: registered data plus one-cycle strobe)
  logic perf_ctrl_snapshot_q;
  logic perf_ctrl_snapshot_qe;
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      perf_ctrl_snapshot_q  <= '0;
      perf_ctrl_snapshot_qe <= 1'b0;
    end else begin
      perf_ctrl_snapshot_qe <= we_perf_ctrl & (|wmask[2]);
      if (we_perf_ctrl) begin
        perf_ctrl_snapshot_q <= req_i.wdata[2] & wmask[2];
      end
    end
  end
  assign reg2hw_o.perf_ctrl.snapshot.q  = perf_ctrl_snapshot_q;
  assign reg2hw_o.perf_ctrl.snapshot.qe = perf_ctrl_snapshot_qe;

  // Read mux
  always_comb begin
    rdata = '0;
    hit   = 1'b1;
    unique case (addr)
      G2D_CSR_ID_OFFSET: begin
        rdata[31:0] = 32'h47324420;
      end
      G2D_CSR_VERSION_OFFSET: begin
        rdata[7:0] = 8'h00;
        rdata[15:8] = 8'h04;
        rdata[23:16] = 8'h00;
      end
      G2D_CSR_HWCFG_OFFSET: begin
        rdata[7:0] = hw2reg_i.hwcfg.data_bytes.d;
        rdata[15:8] = hw2reg_i.hwcfg.addr_w.d;
        rdata[20:16] = hw2reg_i.hwcfg.kick_depth.d;
        rdata[24] = hw2reg_i.hwcfg.cfg_async.d;
        rdata[25] = hw2reg_i.hwcfg.mem_async.d;
        rdata[26] = hw2reg_i.hwcfg.feat_family.d;
        rdata[27] = hw2reg_i.hwcfg.feat_gauss.d;
        rdata[28] = hw2reg_i.hwcfg.feat_yuv.d;
        rdata[29] = hw2reg_i.hwcfg.feat_color.d;
        rdata[30] = hw2reg_i.hwcfg.feat_radial.d;
        rdata[31] = hw2reg_i.hwcfg.feat_mask.d;
      end
      G2D_CSR_SCRATCH_OFFSET: begin
        rdata[31:0] = scratch_value_q;
      end
      G2D_CSR_CTRL_OFFSET: begin
      end
      G2D_CSR_STATUS_OFFSET: begin
        rdata[0] = hw2reg_i.status.idle.d;
        rdata[1] = hw2reg_i.status.halted.d;
        rdata[2] = hw2reg_i.status.soft_reset_busy.d;
        rdata[3] = hw2reg_i.status.cmd_active.d;
        rdata[12:8] = hw2reg_i.status.kick_free.d;
      end
      G2D_CSR_IRQ_STATUS_OFFSET: begin
        rdata[0] = irq_status_fence_q;
        rdata[1] = irq_status_error_q;
        rdata[2] = irq_status_idle_q;
      end
      G2D_CSR_IRQ_ENABLE_OFFSET: begin
        rdata[0] = irq_enable_fence_q;
        rdata[1] = irq_enable_error_q;
        rdata[2] = irq_enable_idle_q;
      end
      G2D_CSR_CMD_ADDR_OFFSET: begin
        rdata[31:3] = cmd_addr_addr_q;
      end
      G2D_CSR_CMD_KICK_OFFSET: begin
      end
      G2D_CSR_FENCE_SEQ_OFFSET: begin
        rdata[31:0] = hw2reg_i.fence_seq.value.d;
      end
      G2D_CSR_ERR_STATUS_OFFSET: begin
        rdata[0] = err_status_cmd_decode_q;
        rdata[1] = err_status_bad_state_q;
        rdata[2] = err_status_addr_range_q;
        rdata[3] = err_status_axi_rd_q;
        rdata[4] = err_status_axi_wr_q;
        rdata[5] = err_status_kick_ovf_q;
      end
      G2D_CSR_ERR_ADDR_OFFSET: begin
        rdata[31:0] = hw2reg_i.err_addr.addr.d;
      end
      G2D_CSR_ERR_CMD_ADDR_OFFSET: begin
        rdata[31:0] = hw2reg_i.err_cmd_addr.addr.d;
      end
      G2D_CSR_MEM_BASE_HI_OFFSET: begin
        rdata[31:0] = mem_base_hi_addr_q;
      end
      G2D_CSR_ADDR_WIN_LO_OFFSET: begin
        rdata[31:6] = addr_win_lo_addr_q;
      end
      G2D_CSR_ADDR_WIN_HI_OFFSET: begin
        rdata[5:0] = 6'h3f;
        rdata[31:6] = addr_win_hi_addr_q;
      end
      G2D_CSR_CUR_CMD_ADDR_OFFSET: begin
        rdata[31:0] = hw2reg_i.cur_cmd_addr.addr.d;
      end
      G2D_CSR_DBG_CTRL_OFFSET: begin
      end
      G2D_CSR_DBG_STATUS_OFFSET: begin
        rdata[6:0] = dbg_status_ram_coll_q;
      end
      G2D_CSR_WR_SIG_OFFSET: begin
        rdata[31:0] = hw2reg_i.wr_sig.value.d;
      end
      G2D_CSR_MEM_ATTR_OFFSET: begin
        rdata[3:0] = mem_attr_ar_cache_q;
        rdata[6:4] = mem_attr_ar_prot_q;
        rdata[11:8] = mem_attr_ar_qos_q;
        rdata[19:16] = mem_attr_aw_cache_q;
        rdata[22:20] = mem_attr_aw_prot_q;
        rdata[27:24] = mem_attr_aw_qos_q;
      end
      G2D_CSR_MEM_QOS_OFFSET: begin
        rdata[4:0] = mem_qos_rd_max_q;
        rdata[12:8] = mem_qos_wr_max_q;
        rdata[23:16] = mem_qos_rd_gap_q;
        rdata[31:24] = mem_qos_wr_gap_q;
      end
      G2D_CSR_PERF_CTRL_OFFSET: begin
        rdata[0] = perf_ctrl_en_q;
      end
      G2D_CSR_PERF_CYCLES_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_cycles.value.d;
      end
      G2D_CSR_PERF_BUSY_CYCLES_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_busy_cycles.value.d;
      end
      G2D_CSR_PERF_DRAWS_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_draws.value.d;
      end
      G2D_CSR_PERF_PIXELS_OUT_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_pixels_out.value.d;
      end
      G2D_CSR_PERF_RD_BEATS_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_rd_beats.value.d;
      end
      G2D_CSR_PERF_WR_BEATS_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_wr_beats.value.d;
      end
      G2D_CSR_PERF_RD_STALL_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_rd_stall.value.d;
      end
      G2D_CSR_PERF_WR_STALL_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_wr_stall.value.d;
      end
      G2D_CSR_PERF_DRAIN_CYC_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_drain_cyc.value.d;
      end
      G2D_CSR_PERF_SRC_CACHE_MISS_OFFSET: begin
        rdata[31:0] = hw2reg_i.perf_src_cache_miss.value.d;
      end
      default: hit = 1'b0;
    endcase
  end

  assign rsp_o.ready = 1'b1;
  assign rsp_o.rdata = (req_i.valid & ~req_i.write) ? rdata : '0;
  assign rsp_o.error = req_i.valid & ~hit;

endmodule
